--
-- Table structure for table `faculty`
--

DROP TABLE IF EXISTS `faculty`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `faculty` (
  `faculty_id` bigint unsigned NOT NULL,
  `office_number` varchar(50) DEFAULT NULL,
  `rank` varchar(50) DEFAULT NULL,
  `faculty_type` varchar(50) DEFAULT NULL,
  `dept_id` varchar(10) DEFAULT NULL,
  `email` varchar(200) DEFAULT NULL,
  `phone_number` varchar(40) DEFAULT NULL,
  `hire_date` date DEFAULT NULL,
  PRIMARY KEY (`faculty_id`),
  KEY `idx_faculty_dept` (`dept_id`),
  CONSTRAINT `fk_faculty_primary_dept` FOREIGN KEY (`dept_id`) REFERENCES `departments` (`dept_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_faculty_user` FOREIGN KEY (`faculty_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

