DROP TABLE IF EXISTS `faculty_departments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `faculty_departments` (
  `faculty_id` bigint unsigned NOT NULL,
  `dept_id` varchar(10) NOT NULL,
  `percent_time` int DEFAULT NULL,
  `date_of_appointment` date DEFAULT NULL,
  PRIMARY KEY (`faculty_id`,`dept_id`),
  KEY `fk_fac_dept_dept` (`dept_id`),
  CONSTRAINT `fk_fac_dept_dept` FOREIGN KEY (`dept_id`) REFERENCES `departments` (`dept_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_fac_dept_faculty` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`faculty_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

