--
-- Table structure for table `faculty_history`
--

DROP TABLE IF EXISTS `faculty_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `faculty_history` (
  `faculty_id` bigint unsigned NOT NULL,
  `crn` bigint unsigned NOT NULL,
  `course_id` varchar(30) NOT NULL,
  `semester_id` varchar(16) NOT NULL,
  PRIMARY KEY (`faculty_id`,`crn`),
  KEY `fk_fac_hist_class` (`crn`),
  KEY `fk_fac_hist_course` (`course_id`),
  KEY `fk_fac_hist_semester` (`semester_id`),
  CONSTRAINT `fk_fac_hist_class` FOREIGN KEY (`crn`) REFERENCES `classes` (`crn`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_fac_hist_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
