DROP TABLE IF EXISTS `student_declaration_change_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_declaration_change_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint unsigned NOT NULL,
  `change_kind` enum('major','minor') NOT NULL,
  `old_dept_id` varchar(10) DEFAULT NULL,
  `new_dept_id` varchar(10) DEFAULT NULL,
  `actor_kind` enum('admin','student','system') NOT NULL DEFAULT 'admin',
  `actor_auth_id` bigint unsigned DEFAULT NULL,
  `actor_user_id` bigint unsigned DEFAULT NULL,
  `note` varchar(500) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_decl_change_student_created` (`student_id`,`created_at`),
  KEY `idx_decl_change_actor_auth` (`actor_auth_id`),
  CONSTRAINT `fk_decl_change_actor_auth` FOREIGN KEY (`actor_auth_id`) REFERENCES `auth_users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_decl_change_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
