--
-- Table structure for table `student_departments`
--

DROP TABLE IF EXISTS `student_departments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_departments` (
  `student_id` bigint unsigned NOT NULL,
  `dept_id` varchar(10) NOT NULL,
  `declaration_role` enum('major','minor') NOT NULL DEFAULT 'major',
  `date_of_declaration` date DEFAULT NULL,
  `major_student_id` bigint unsigned GENERATED ALWAYS AS ((case when (`declaration_role` = _utf8mb4'major') then `student_id` else NULL end)) VIRTUAL,
  `minor_student_id` bigint unsigned GENERATED ALWAYS AS ((case when (`declaration_role` = _utf8mb4'minor') then `student_id` else NULL end)) VIRTUAL,
  PRIMARY KEY (`student_id`,`dept_id`),
  UNIQUE KEY `uq_student_one_major` (`major_student_id`),
  UNIQUE KEY `uq_student_one_minor` (`minor_student_id`),
  KEY `fk_stu_dept_dept` (`dept_id`),
  CONSTRAINT `fk_stu_dept_dept` FOREIGN KEY (`dept_id`) REFERENCES `departments` (`dept_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_stu_dept_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

