--
-- Table structure for table `student_history`
--

DROP TABLE IF EXISTS `student_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_history` (
  `student_id` bigint unsigned NOT NULL,
  `crn` bigint unsigned NOT NULL,
  `course_id` varchar(30) NOT NULL,
  `semester_id` varchar(16) NOT NULL,
  `grade` varchar(5) DEFAULT NULL,
  PRIMARY KEY (`student_id`,`crn`),
  KEY `fk_stu_hist_class` (`crn`),
  KEY `fk_stu_hist_course` (`course_id`),
  KEY `fk_stu_hist_semester` (`semester_id`),
  KEY `fk_stu_hist_grade` (`grade`),
  CONSTRAINT `fk_stu_hist_class` FOREIGN KEY (`crn`) REFERENCES `classes` (`crn`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_stu_hist_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_stu_hist_grade` FOREIGN KEY (`grade`) REFERENCES `grade_letters` (`grade`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_stu_hist_semester` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`semester_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_stu_hist_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

